SELECT name, description, icon_url, apollo_organization_id, website_url, linkedin_url, twitter_url, facebook_url, industry, keywords, technologies, estimated_num_employees, annual_revenue, annual_revenue_printed, total_funding, total_funding_printed, latest_funding_stage, latest_funding_round_date, founded_year, publicly_traded_symbol, publicly_traded_exchange, phone, raw_address, street_address, city, state, postal_code, country, raw FROM crm_domain_directory WHERE LOWER(domain) = $1 LIMIT 1
